begin;
create temporary table fan_test_context as select (select id from public.profiles limit 1) as uid,gen_random_uuid() as match_id,gen_random_uuid() as other_uid;
grant select on fan_test_context to authenticated;
do $$begin if (select uid from fan_test_context) is null then raise exception 'A profile is required for this rollback-only test';end if;end$$;
insert into public.matches select (jsonb_populate_record(null::public.matches,to_jsonb(m)||jsonb_build_object('id',c.match_id,'kickoff',now()+interval '4 hours','status','scheduled','goal_fixture_id',null,'goal_fixture_api_id',null))).* from public.matches m cross join fan_test_context c where (select count(*) from public.players p where p.club_id=m.home_club_id and p.active)>=11 limit 1;
select set_config('request.jwt.claims',jsonb_build_object('sub',c.uid,'role','authenticated')::text,true) from fan_test_context c;
set local role authenticated;
do $$declare mid uuid:=(select match_id from fan_test_context);blocked boolean;begin
 perform public.save_fan_guess(mid,'winner','{"value":"home","points":25,"user_id":"spoof"}'::jsonb);
 if (select choice ? 'points' or choice ? 'user_id' or points is not null from public.fan_guesses where match_id=mid) then raise exception 'Client injected scoring fields';end if;
 if (select count(*) from public.fan_guesses where match_id=mid)<>1 then raise exception 'Own guess cannot be read';end if;
 blocked:=false;
 begin update public.fan_guesses set points=25 where match_id=mid;exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Direct scoring write allowed';end if;
 blocked:=false;
 begin perform public.settle_fan_guess_facts(mid,'{"winner":"home"}'::jsonb);exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'A fan can settle scores';end if;
 blocked:=false;
 begin perform public.save_fan_guess(mid,'exact_score','{"home":-1,"away":2}'::jsonb);exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Negative score accepted';end if;
 blocked:=false;
 begin perform public.save_fan_guess(mid,'lineup',jsonb_build_object('side','home','players',jsonb_build_array('duplicate','duplicate','duplicate','duplicate','duplicate','duplicate','duplicate','duplicate','duplicate','duplicate','duplicate')));exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Invalid duplicate lineup accepted';end if;
 perform public.save_fan_guess(mid,'exact_score','{"home":1,"away":0}'::jsonb);
 if not exists(select 1 from public.predictions where match_id=mid and home_score=1 and away_score=0) then raise exception 'Legacy score compatibility failed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',(select other_uid from fan_test_context),'role','authenticated')::text,true);
 if exists(select 1 from public.fan_guesses where match_id=mid) then raise exception 'Another fan can read private choices';end if;
end$$;
set local role postgres;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select public.settle_fan_guess_facts((select match_id from fan_test_context),' {"winner":"home","exact_score":{"home":1,"away":0}}'::jsonb);
do $$declare mid uuid:=(select match_id from fan_test_context);lineup jsonb;fixture text:='rollback-only-fan-guess-fixture';begin
 if (select points from public.fan_guesses where match_id=mid and kind='winner')<>10 or (select points from public.fan_guesses where match_id=mid and kind='exact_score')<>25 then raise exception 'Trusted settlement returned incorrect points';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',(select uid from fan_test_context),'role','authenticated')::text,true);
 update public.matches set kickoff=now()+interval '30 minutes' where id=mid;
 begin perform public.save_fan_guess(mid,'lineup','{}');raise exception 'Lineup within final hour accepted';exception when raise_exception then if sqlerrm<>'Lineup predictions closed' then raise;end if;end;
 update public.matches set kickoff=now()+interval '4 hours',goal_fixture_id=fixture where id=mid;
 select jsonb_build_object('side','home','players',jsonb_agg(id)) into lineup from(select id from public.players where active and club_id=(select home_club_id from public.matches where id=mid) limit 11) p;
 insert into public.football_cache(cache_key,payload,expires_at,updated_at) values('/fixtures/'||fixture||'/lineups','{"home":{"startingLineups":[{"playerKey":"published"}]}}',now()+interval '1 hour',now());
 begin perform public.save_fan_guess(mid,'lineup',lineup);raise exception 'Published lineup accepted';exception when raise_exception then if sqlerrm<>'Official lineup already published' then raise;end if;end;
 update public.matches set kickoff=now()-interval '1 minute' where id=mid;
 begin perform public.save_fan_guess(mid,'winner','{"value":"away"}');raise exception 'Closed guess accepted';exception when raise_exception then if sqlerrm<>'Predictions closed' then raise;end if;end;
end$$;
rollback;
select jsonb_build_object('passed',true,'rolled_back',true,'checks',jsonb_build_array('own read','other fan isolation','no direct score write','service-only settlement','discard injected fields','negative score rejection','duplicate lineup rejection','legacy predictions compatibility','trusted scoring','kickoff deadline','lineup hour deadline','partial published lineup lock')) as test_result;
